import java.io.*;
import java.util.*;

public class C4_Variant5 {
    private InputStream is;
    private PrintWriter out;
    private String INPUT = "";

    void solve() {
        int n = ni();
        long[][] circles = new long[n][3];
        for (int i = 0; i < n; i++) {
            circles[i][0] = ni();
            circles[i][1] = ni();
            circles[i][2] = ni();
        }

        List<double[]> points = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                double[] angles = computeIntersectionAngles(
                    circles[i][0], circles[i][1], circles[i][2],
                    circles[j][0], circles[j][1], circles[j][2]
                );
                for (double angle : angles) {
                    double x = circles[i][0] + circles[i][2] * Math.cos(angle);
                    double y = circles[i][1] + circles[i][2] * Math.sin(angle);
                    points.add(new double[]{x, y});
                }
            }
        }

        List<double[]> uniquePoints = new ArrayList<>();
        for (double[] pt : points) {
            boolean isDuplicate = false;
            for (double[] existing : uniquePoints) {
                double dx = pt[0] - existing[0];
                double dy = pt[1] - existing[1];
                if (dx * dx + dy * dy < 1e-12) {
                    isDuplicate = true;
                    break;
                }
            }
            if (!isDuplicate) {
                uniquePoints.add(pt);
            }
        }

        int nodeCount = uniquePoints.size();
        int edgeCount = 0;
        for (int i = 0; i < n; i++) {
            int count = 0;
            for (double[] pt : uniquePoints) {
                double dx = pt[0] - circles[i][0];
                double dy = pt[1] - circles[i][1];
                double distSq = dx * dx + dy * dy;
                if (Math.abs(distSq - circles[i][2] * circles[i][2]) < 1e-12) {
                    count++;
                }
            }
            edgeCount += count;
        }

        out.println(edgeCount - nodeCount + 2);
    }

    private static final double EPS = 1e-10;

    public static double[] computeIntersectionAngles(long x1, long y1, long r1, long x2, long y2, long r2) {
        long dx = x2 - x1;
        long dy = y2 - y1;
        long d2 = dx * dx + dy * dy;
        long diff = r1 - r2;
        long sum = r1 + r2;

        if (d2 < diff * diff || d2 > sum * sum) {
            return new double[0];
        }

        double baseAngle = Math.atan2(dy, dx);
        double distance = Math.sqrt(d2);
        double angleOffset = Math.acos((d2 + r1 * r1 - r2 * r2) / (2 * distance * r1));

        return new double[]{baseAngle - angleOffset, baseAngle + angleOffset};
    }

    void run() throws Exception {
        is = oj ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);

        long start = System.currentTimeMillis();
        solve();
        out.flush();
        if (!oj) System.out.println(System.currentTimeMillis() - start + "ms");
    }

    public static void main(String[] args) throws Exception {
        new C4_Variant5().run();
    }

    private byte[] buffer = new byte[1024];
    private int bufferLen = 0, bufferPtr = 0;

    private int readByte() {
        if (bufferLen == -1) throw new InputMismatchException();
        if (bufferPtr >= bufferLen) {
            bufferPtr = 0;
            try {
                bufferLen = is.read(buffer);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (bufferLen <= 0) return -1;
        }
        return buffer[bufferPtr++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while ((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char) skip(); }

    private String ns() {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while (!isSpaceChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n) {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while (p < n && !isSpaceChar(b)) {
            buf[p++] = (char) b;
            b = readByte();
        }
        return p == n ? buf : Arrays.copyOf(buf, p);
    }

    private int[] na(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = ni();
        return a;
    }

    private int ni() {
        int num = 0, b;
        boolean minus = false;
        while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl() {
        long num = 0;
        int b;
        boolean minus = false;
        while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private boolean oj = System.getProperty("ONLINE_JUDGE") != null;
}
